func (q *Queries) UpsertChannelUserPermission(ctx context.Context, arg UpsertChannelUserPermissionParams) error {
	_, err := q.db.ExecContext(ctx, upsertChannelUserPermission,
		arg.ChannelID,
		arg.UserID,
		arg.Allow,
		arg.Deny,
	)
	return err
}
